type NominatimAddress={city?:string;town?:string;village?:string;municipality?:string;county?:string;state?:string;state_district?:string};
type NominatimPlace={place_id:number;display_name:string;lat:string;lon:string;address?:NominatimAddress};
const nominatimCache=new Map<string,unknown>();
let lastNominatimRequestAt=0;
async function fetchNominatim<T>(url:URL):Promise<T>{
  const key=url.toString();
  if(nominatimCache.has(key))return nominatimCache.get(key) as T;
  const delay=Math.max(0,1100-(Date.now()-lastNominatimRequestAt));
  if(delay)await new Promise(resolve=>window.setTimeout(resolve,delay));
  lastNominatimRequestAt=Date.now();
  const response=await fetch(key,{headers:{Accept:'application/json','Accept-Language':navigator.language||'en'}});
  if(!response.ok)throw new Error('The address service is temporarily unavailable. Enter the location manually or try again shortly.');
  const value=await response.json() as T;
  nominatimCache.set(key,value);
  return value;
}

function stationLocationFromPlace(place:NominatimPlace){
  const address=place.address??{};
  return {
    address:place.display_name,
    city:address.city??address.town??address.village??address.municipality??address.county??'',
    state:address.state??address.state_district??'',
    latitude:Number(place.lat).toFixed(7),
    longitude:Number(place.lon).toFixed(7),
  };
}

let razorpayLoader:Promise<void>|undefined;
function loadRazorpayCheckout(){if(window.Razorpay)return Promise.resolve();razorpayLoader??=new Promise<void>((resolve,reject)=>{const existing=document.querySelector<HTMLScriptElement>('script[data-tekwatt-razorpay]');if(existing){existing.addEventListener('load',()=>resolve(),{once:true});existing.addEventListener('error',()=>reject(new Error('Razorpay checkout could not be loaded. Check your internet connection.')),{once:true});return;}const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.async=true;script.dataset.tekwattRazorpay='true';script.onload=()=>resolve();script.onerror=()=>reject(new Error('Razorpay checkout could not be loaded. Check your internet connection.'));document.head.appendChild(script);});return razorpayLoader;}

function downloadCsv(fileName:string,headers:string[],rows:(string|number|undefined)[][]){const quote=(value:string|number|undefined)=>`"${String(value??'').replaceAll('"','""')}"`;const csv=[headers,...rows].map(row=>row.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=fileName;link.click();URL.revokeObjectURL(url);}

function decodeAccessToken(token:string){const part=token.split('.')[1];if(!part)throw new Error('Invalid access token');const normalized=part.replace(/-/g,'+').replace(/_/g,'/');return JSON.parse(atob(normalized.padEnd(Math.ceil(normalized.length/4)*4,'='))) as {sub:string;email?:string;roles?:string[]};}

const configuredIdleMinutes=Number(import.meta.env.VITE_IDLE_TIMEOUT_MINUTES??15);const idleTimeoutMs=(Number.isFinite(configuredIdleMinutes)&&configuredIdleMinutes>0?configuredIdleMinutes:15)*60_000;const idleWarningMs=Math.min(60_000,idleTimeoutMs/2);const activityStorageKey='tekwatt-last-user-activity';
function IdleSessionGuard(){const [remaining,setRemaining]=useState<number|null>(null);const signingOut=useRef(false);const continueSession=()=>{localStorage.setItem(activityStorageKey,String(Date.now()));setRemaining(null);};const logoutNow=()=>{if(signingOut.current)return;signingOut.current=true;const refreshToken=sessionStorage.getItem('tekwatt-refresh-token');const finish=()=>{sessionStorage.clear();window.location.reload();};if(refreshToken)void api.logout(refreshToken).catch(()=>{}).finally(finish);else finish();};useEffect(()=>{continueSession();const check=()=>{const last=Number(localStorage.getItem(activityStorageKey)??Date.now());const timeLeft=idleTimeoutMs-(Date.now()-last);if(timeLeft<=0){logoutNow();return;}setRemaining(timeLeft<=idleWarningMs?timeLeft:null);};const activity=()=>continueSession();const events=['pointerdown','keydown','touchstart','scroll'] as const;events.forEach(name=>window.addEventListener(name,activity,{passive:true}));window.addEventListener('storage',check);const timer=window.setInterval(check,1000);return()=>{events.forEach(name=>window.removeEventListener(name,activity));window.removeEventListener('storage',check);window.clearInterval(timer);};},[]);return remaining===null?null:<div className="idle-warning-backdrop" role="dialog" aria-modal="true" aria-labelledby="idle-warning-title"><div className="idle-warning"><div className="metric-icon amber"><ShieldCheck/></div><span className="eyebrow">SESSION SECURITY</span><h2 id="idle-warning-title">You’ll be signed out soon</h2><p>No activity was detected. Your session will end in <strong>{Math.max(1,Math.ceil(remaining/1000))} seconds</strong>.</p><div className="modal-actions"><button className="secondary" onClick={logoutNow}>Sign out now</button><button className="primary" autoFocus onClick={continueSession}>Continue session</button></div></div></div>}

async function resolveLoginIdentity(token:string,email:string,firstAccount=false):Promise<LoginIdentity>{
  const claims=decodeAccessToken(token);const normalizedEmail=(claims.email??email).trim().toLowerCase();
  try{
    const tenants=await api.tenants();
    for(const tenant of tenants){
      const results=await Promise.allSettled([api.users(tenant.id),api.partners(tenant.id),api.technicians(tenant.id),api.administrators(tenant.id)]);
      const values=<T,>(index:number):T[]=>results[index].status==='fulfilled'?results[index].value as T[]:[];
      const admin=values<Administrator>(3).find(item=>item.authUserId===claims.sub||item.email.toLowerCase()===normalizedEmail);if(admin)return{userId:claims.sub,email:normalizedEmail,name:admin.name,role:'ADMIN'};
      const technician=values<Technician>(2).find(item=>item.authUserId===claims.sub||item.email.toLowerCase()===normalizedEmail);if(technician)return{userId:claims.sub,email:normalizedEmail,name:technician.name,role:'TECHNICIAN'};
      const partner=values<Partner>(1).find(item=>item.authUserId===claims.sub||item.appLoginEmail?.toLowerCase()===normalizedEmail);if(partner)return{userId:claims.sub,email:normalizedEmail,name:partner.companyName,role:'PARTNER'};
      const customer=values<UserProfile>(0).find(item=>item.authUserId===claims.sub||item.email.toLowerCase()===normalizedEmail);if(customer)return{userId:claims.sub,email:normalizedEmail,name:customer.fullName??(`${customer.firstName??''} ${customer.lastName??''}`.trim()||customer.email),role:'CUSTOMER'};
    }
  }catch{/* Login remains available while optional directory services recover. */}
  const claimed=(claims.roles?.[0]??'').replace(/^ROLE_/,'').toUpperCase();
  const role:AuthRole=firstAccount||normalizedEmail==='admin@tekwatt.in'?'ADMIN':claimed==='PARTNER'?'PARTNER':claimed==='TECHNICIAN'?'TECHNICIAN':claimed==='ADMIN'?'ADMIN':'CUSTOMER';
  return{userId:claims.sub,email:normalizedEmail,name:normalizedEmail.split('@')[0],role};
}

