const stationNameOf=(charger:Charger)=>charger.stationName?.trim()||charger.stationId;
const stationLocationOf=(charger:Charger)=>[charger.city,charger.state].filter(Boolean).join(', ');
const stationAddressOf=(charger:Charger)=>[charger.address,charger.city,charger.state].filter((value,index,all)=>Boolean(value)&&all.indexOf(value)===index).join(', ');
const chargerContextOf=(charger:Charger)=>[stationNameOf(charger),charger.stationId!==stationNameOf(charger)?charger.stationId:'',stationLocationOf(charger)].filter(Boolean).join(' · ');
const uniqueStationRecords=(chargers:Charger[])=>chargers.filter((charger,index,all)=>all.findIndex(item=>stationNameOf(item)===stationNameOf(charger))===index);

const stationRowsFromChargers = (chargers: Charger[]) => {
  const grouped = new Map<string, Charger[]>();
  chargers.forEach(charger => {
    const key = stationNameOf(charger);
    grouped.set(key, [...(grouped.get(key) ?? []), charger]);
  });
  return [...grouped.entries()].map(([name, stationChargers], index) => {
    const first = stationChargers[0];
    const online = stationChargers.some(charger => ['AVAILABLE','ONLINE','CHARGING'].includes(charger.status));
    const power = stationChargers.reduce((total, charger) => total + Number(charger.powerKw ?? 0), 0);
    return { name, city: stationAddressOf(first) || `${first.vendor} ${first.model}`, chargers: stationChargers.length, power: `${power || first.powerKw || 0} kW`, status: online ? 'Online' : first.status, usage: 35 + (index * 13) % 55 };
  });
};

