function Login({ onLogin, onDemo }: { onLogin: (email: string, password: string, register: boolean) => Promise<void>; onDemo: () => void }) {
  const [email, setEmail] = useState('admin@tekwatt.in');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(()=>{const notice=sessionStorage.getItem('tekwatt-auth-notice')??'';sessionStorage.removeItem('tekwatt-auth-notice');return notice;});
  const submit = async (event: FormEvent, register = false) => {
    event.preventDefault(); setLoading(true); setError('');
    try { await onLogin(email, password, register); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to sign in'); }
    finally { setLoading(false); }
  };
  return <main className="login-page">
    <section className="login-story">
      <Brand />
      <div className="story-content">
        <span className="eyebrow light">EV CHARGING, ORCHESTRATED</span>
        <h1>One network.<br />Infinite momentum.</h1>
        <p>Operate every station, charger and customer journey from one intelligent energy platform.</p>
        <div className="pulse-line"><span /> Network operating normally</div>
      </div>
    </section>
    <section className="login-panel">
      <form className="login-card" onSubmit={submit}>
        <div className="mobile-brand"><Brand /></div>
        <span className="eyebrow">WELCOME BACK</span>
        <h2>Sign in to Nexus</h2>
        <p>Enter your customer, partner, technician, or administrator credentials.</p>
        <label>Email address<input type="email" value={email} onChange={e => setEmail(e.target.value)} /></label>
        <label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Your backend account password" /></label>
        {error && <ErrorAlert title="Sign-in unsuccessful" message={error} />}
        <button className="primary wide" type="submit" disabled={loading}>{loading ? 'Connecting…' : 'Sign in'} <Bolt size={18} /></button>
        <button className="secondary wide" type="button" disabled={loading || password.length < 12} onClick={event => submit(event, true)}>Create first account</button>
        <button className="demo-link" type="button" onClick={onDemo}>Explore with demo data</button>
        <small>Account creation requires a password of at least 12 characters.</small>
      </form>
    </section>
  </main>;
}

function Sidebar({ page, activeView = '', navigate, open, close, chargerCount, permissions, tenants, selectedTenantId, selectTenant, manageWorkspaces, health }: { page: Page; activeView?: string; navigate: (page: Page, view?: string) => void; open: boolean; close: () => void; chargerCount: number; permissions:Set<string>;tenants:Tenant[];selectedTenantId?:string;selectTenant:(id:string)=>void;manageWorkspaces?:()=>void;health:'operational'|'degraded'|'checking'|'offline' }) {
  const [expanded,setExpanded]=useState<Page|null>(page);
  const [workspaceOpen,setWorkspaceOpen]=useState(false);const selectedTenant=tenants.find(item=>item.id===selectedTenantId)??tenants[0];
  useEffect(()=>setExpanded(page),[page]);
  const go=(target:Page,view?:string)=>navigate(target,view);
  return <aside className={`sidebar ${open ? 'open' : ''}`}>
    <IdleSessionGuard/>
    <div className="sidebar-head"><Brand /><button className="icon mobile-only" onClick={close}><X /></button></div>
    <div className="workspace-switcher"><button className="workspace" type="button" aria-expanded={workspaceOpen} onClick={()=>setWorkspaceOpen(!workspaceOpen)}><span className="avatar mini">{selectedTenant?.name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'TW'}</span><span><small>WORKSPACE</small><strong>{selectedTenant?.name??'No workspace'}</strong></span><ChevronDown className={workspaceOpen?'open':''} size={16}/></button>{workspaceOpen&&<div className="workspace-menu">{tenants.map(tenant=><button type="button" key={tenant.id} className={tenant.id===selectedTenant?.id?'active':''} onClick={()=>{selectTenant(tenant.id);setWorkspaceOpen(false);close();}}><span>{tenant.name}</span><small>{tenant.slug}</small></button>)}{manageWorkspaces&&<button type="button" className="workspace-manage" onClick={()=>{manageWorkspaces();setWorkspaceOpen(false);}}><Plus size={14}/> Manage workspaces</button>}</div>}</div>
    <nav>{nav.filter(item=>item.label==='Dashboard'?permissions.has('Dashboard'):(navigationScreens[item.label]?.some(screen=>permissions.has(screen))??permissions.has(item.label))).map(item => {
      const screens=(navigationScreens[item.label]??[]).filter(screen=>permissions.has(screen));
      const hasChildren=screens.length>0;
      const isExpanded=expanded===item.label;
      return <div className="nav-group" key={item.label}><button className={`nav-parent ${page === item.label ? 'active' : ''}`} aria-expanded={hasChildren?isExpanded:undefined} onClick={() => {
        if(hasChildren&&isExpanded){setExpanded(null);return;}
        setExpanded(hasChildren?item.label:null);
        if(page!==item.label)go(item.label,screens[0]);
        if(!hasChildren)close();
      }}><item.icon size={19} /><span>{item.display ?? item.label}</span>{item.label === 'Stations' && <em>{chargerCount}</em>}{hasChildren&&<ChevronDown className={`nav-chevron ${isExpanded?'open':''}`} size={14}/>}</button>{isExpanded&&hasChildren&&<div className="nav-children">{screens.map(screen=><button key={screen} aria-current={activeView===screen?'page':undefined} className={activeView===screen?'active':''} onClick={()=>{go(item.label,screen);close();}}><Zap className="submenu-bolt" size={11}/>{screen}</button>)}</div>}</div>;
    })}</nav>
    <div className={`sidebar-foot ${health}`}><div className="health-dot" /><div><strong>{health==='operational'?'All systems operational':health==='degraded'?'Some services are unavailable':health==='checking'?'Checking service health':'Platform offline'}</strong><small>{health==='degraded'?'Open the current warning for details':health==='checking'?'Waiting for live status':'Updated just now'}</small></div></div>
  </aside>;
}

function Header({ page, dark, toggleDark, openMenu, logout, navigate, realtime, identity, permissions }: { page: Page; dark: boolean; toggleDark: () => void; openMenu: () => void; logout: () => void; navigate: (page: Page, view?: string) => void; realtime: 'live' | 'connecting' | 'offline'; identity:LoginIdentity; permissions:Set<string> }) {
  const canOpen=(item:{label:Page})=>item.label==='Dashboard'?permissions.has('Dashboard'):(navigationScreens[item.label]?.some(screen=>permissions.has(screen))??permissions.has(item.label));
  const search = (value: string) => { const query=value.trim().toLowerCase();if(!query)return;const targets=nav.filter(canOpen).flatMap(item=>{const parent:{page:Page;view?:string;label:string}={page:item.label,label:item.display??item.label};const children=(navigationScreens[item.label]??[]).filter(screen=>permissions.has(screen)).map(screen=>({page:item.label,view:screen,label:screen}));return[parent,...children];});const match=targets.find(item=>item.label.toLowerCase()===query)??targets.find(item=>item.label.toLowerCase().includes(query));if(match)navigate(match.page,match.view); };
  const initials=identity.name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'TW';
  return <header><button className="icon mobile-only" onClick={openMenu}><Menu /></button><div><small>{identity.role} PORTAL</small><h2>{page}</h2></div><div className="header-actions"><label className="search"><Search size={17} /><input placeholder="Search sections" onKeyDown={event => { if (event.key === 'Enter') search(event.currentTarget.value); }} /></label><span className={`live ${realtime}`} title="Real-time server event connection"><i /> {realtime === 'live' ? 'LIVE' : realtime === 'connecting' ? 'RECONNECTING' : 'OFFLINE'}</span><button className="icon" onClick={toggleDark} aria-label="Toggle theme">{dark ? <Sun /> : <Moon />}</button><button className="icon notification" onClick={() => window.alert('No new platform notifications.')} aria-label="Notifications"><Bell /><i /></button><button className="profile" onClick={() => permissions.has('Account Settings')?navigate('Settings','Account Settings'):navigate('Dashboard')}><span className="avatar">{initials}</span><span><strong>{identity.name}</strong><small>{identity.role[0]+identity.role.slice(1).toLowerCase()}</small></span><ChevronDown size={16} /></button><button className="icon logout" onClick={logout} title="Sign out"><LogOut /></button></div></header>;
}

function WorkspaceModal({tenants,currentId,close,saved}:{tenants:Tenant[];currentId?:string;close:()=>void;saved:(tenant:Tenant)=>Promise<void>}){
  const [editingId,setEditingId]=useState(currentId??'');const editing=tenants.find(item=>item.id===editingId);const [form,setForm]=useState({name:editing?.name??'',slug:editing?.slug??'',contactEmail:editing?.contactEmail??''});const [error,setError]=useState('');const [saving,setSaving]=useState(false);
  useEffect(()=>setForm({name:editing?.name??'',slug:editing?.slug??'',contactEmail:editing?.contactEmail??''}),[editingId,editing?.updatedAt]);
  const submit=async(event:FormEvent)=>{event.preventDefault();setSaving(true);setError('');try{const body={...form,slug:form.slug.trim().toLowerCase()};const tenant=editingId?await api.updateTenant(editingId,body):await api.createTenant(body);await saved(tenant);setEditingId(tenant.id);}catch(reason){setError(reason instanceof Error?reason.message:'Workspace could not be saved');}finally{setSaving(false);}};
  const createNew=()=>{setEditingId('');setForm({name:'',slug:'',contactEmail:''});setError('');};
  return <div className="modal-backdrop" onMouseDown={event=>{if(event.currentTarget===event.target)close();}}><form className="modal" onSubmit={submit}><div className="modal-head"><div><span className="eyebrow">TENANT MANAGEMENT</span><h2>Workspaces</h2><p>Create and switch between isolated operating environments.</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="workspace-admin-list">{tenants.map(tenant=><button type="button" key={tenant.id} className={editingId===tenant.id?'active':''} onClick={()=>{setEditingId(tenant.id);setError('');}}><strong>{tenant.name}</strong><small>{tenant.slug} · {tenant.status??'ACTIVE'}</small></button>)}<button type="button" className={!editingId?'active new-workspace':''} onClick={createNew}><Plus size={15}/> New workspace</button></div><div className="form-grid"><label>Workspace name<input required maxLength={150} value={form.name} onChange={event=>setForm({...form,name:event.target.value})} placeholder="TekWatt Chennai"/></label><label>Unique slug<input required maxLength={80} pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value={form.slug} onChange={event=>setForm({...form,slug:event.target.value.toLowerCase().replace(/[^a-z0-9-]/g,'-')})} placeholder="tekwatt-chennai"/><small>Lowercase letters, numbers and hyphens only</small></label><label className="full">Contact email<input required type="email" maxLength={254} value={form.contactEmail} onChange={event=>setForm({...form,contactEmail:event.target.value})}/></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={close}>Close</button><button className="primary" disabled={saving}>{saving?'Saving…':editingId?'Save workspace':'Create workspace'}</button></div></form></div>;
}

